Rules.InvariantScript:
Switch(
    Text(Param("screen")),
    "general",
    Trace($"Navigate to Project Main Screen: with ProjectId=>{Param("projectId")}");
    Navigate(
        'Project General Data Screen',
        ScreenTransition.Fade,
        {locGeneralDataTabSelected: "generalDataTab"}
    ),
    "generators",
    Trace($"Navigate to Project General Data Screen: with ProjectId=>{Param("projectId")}");

    Navigate(
        'Project Generators Screen',
        ScreenTransition.Fade,
        {locGeneralDataTabSelected: "generalDataTab"}
    )
);

